import os, csv, json, hashlib
BASE = "storage/shared/agency_lab/analyses/csv"
REPORT = "storage/shared/agency_lab/analyses/axiom_report_v1_2b_interactions_official_v2_1.txt"
FILES = [
    "f1_per_agent.csv","f2_novelty_timeline.csv","f3_timesliced_combined.csv","f3_timesliced_sources.csv",
    "f4_rolling_combined.csv","f4_rolling_sources.csv",
    "joint_metrics_v2_4_per_lineage.csv","joint_metrics_v2_4_per_agent.csv",
    "joint_metrics_v2_5_adjacency.csv","joint_metrics_v2_5_per_lineage_rolling.csv",
    "joint_metrics_v2_6_granger.csv","joint_metrics_v2_7_var_granger.csv",
    "joint_metrics_v2_8_per_lineage_rolling.csv","joint_metrics_v2_8_var_granger.csv",
    "joint_metrics_v2_9_causal_edges.csv",
]
def md5_of_file(p):
    h=hashlib.md5()
    with open(p,"rb") as f:
        for chunk in iter(lambda:f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()
def summarize(p):
    with open(p,"r",encoding="utf-8") as f:
        rows=list(csv.reader(f))
    return {"rows":max(0,len(rows)-1),"cols":(len(rows[0]) if rows else 0),"header":(rows[0] if rows else []),"sample":rows[1:3]}
def main():
    manifest={"csv":{},"report":{}}
    for fn in FILES:
        p=os.path.join(BASE,fn)
        if os.path.exists(p):
            info=summarize(p); info["md5"]=md5_of_file(p); manifest["csv"][fn]=info
        else:
            manifest["csv"][fn]={"missing":True}
    if os.path.exists(REPORT):
        manifest["report"]={"path":REPORT,"md5":md5_of_file(REPORT),"size_bytes":os.path.getsize(REPORT)}
    else:
        manifest["report"]={"missing":True,"path":REPORT}
    out_json=os.path.join(BASE,"qc_manifest.json")
    out_txt=os.path.join(BASE,"qc_manifest.txt")
    with open(out_json,"w",encoding="utf-8") as f: json.dump(manifest,f,indent=2)
    lines=["QC MANIFEST"]
    rep=manifest["report"]; lines.append(f"REPORT OK md5={rep.get('md5')} size={rep.get('size_bytes')}") if "md5" in rep else lines.append("REPORT MISSING")
    for fn,info in manifest["csv"].items():
        if "missing" in info: lines.append(f"{fn}: MISSING")
        else: lines.append(f"{fn}: rows={info['rows']} cols={info['cols']} md5={info['md5']}")
    with open(out_txt,"w",encoding="utf-8") as f: f.write("\n".join(lines)+"\n")
    print("QC_DONE", out_json, out_txt); return 0
if __name__=="__main__":
    import sys
    try: sys.exit(main())
    except Exception as e:
        print("ERROR", str(e)); sys.exit(1)
